//! The pins of slice 7, the ruling body validation, over
//! synthetic packs and records and bodies the suite writes
//! itself. The pack stands above the floor, assembled by the
//! binary from synthetic catchledger and canaryfield
//! documents exactly as the slice 4 pins assemble it, and the
//! rulings are generated by the library over that pack.

use std::path::{Path, PathBuf};
use std::process::Command;

use tameshi::jsonvalue::{parse, JsonValue};
use tameshi::render::render_json;
use tameshi::rulings::{generate_ruling, validate_ruling_body};

fn scratch(name: &str) -> PathBuf {
    let dir =
        std::env::temp_dir().join(format!("tameshi-ruling-body-{}-{name}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("the scratch directory stands");
    dir
}

fn write(dir: &Path, name: &str, text: &str) -> PathBuf {
    let path = dir.join(name);
    std::fs::write(&path, text).expect("the fixture writes");
    path
}

fn run(dir: &Path, args: &[&str]) -> (i32, String) {
    let output = Command::new(env!("CARGO_BIN_EXE_tameshi"))
        .args(args)
        .current_dir(dir)
        .output()
        .expect("the binary runs");
    (
        output.status.code().unwrap_or(-1),
        String::from_utf8_lossy(&output.stderr).to_string(),
    )
}

const SCORECARD: &str = r#"{"fires": 40, "blocks": 6, "judged_commits": 20, "flaky_commits": 1, "flake_rate": 0.05, "runtime_seconds": 900, "runtime_minutes": 15.0, "catches": 3, "false_blocks": 1, "unattributed_blocks": 2, "false_block_rate": 0.1667, "total_cost_usd": 0.12, "cost_per_catch_usd": 0.04}"#;

fn catch_record(days: std::ops::RangeInclusive<i32>) -> String {
    let entries: Vec<String> = days
        .map(|day| {
            format!(
                r#"{{"block_run_id": "{}", "blocked_commit": "0000000000000000000000000000000000000001", "evidence": {{"fix_commits": ["ffffffffffffffffffffffffffffffffffffffff"], "reason": null, "type": "flagged_fix_then_success", "validating_run_id": "900"}}, "flagged_paths": ["src/synthetic.py"], "outcome": "catch", "started_at": "2026-01-{:02}T00:10:00Z"}}"#,
                100 + day,
                day
            )
        })
        .collect();
    format!("[{}]", entries.join(", "))
}

fn cl_pack(days: std::ops::RangeInclusive<i32>) -> String {
    format!(
        r#"{{"format": "catchledger-pack/1", "repo": "synthetic-repo", "check": "unit checks", "scorecard": {SCORECARD}, "catch_record": {}, "canaryfield_results": null, "false_block_rate": 0.1667, "pricing": {{"currency": "USD", "cost_per_minute": "0.008"}}, "source": {{"ci_history_sha256": null, "git_history_sha256": null, "canaryfield_results_sha256": null}}}}"#,
        catch_record(days)
    )
}

fn canary() -> String {
    let rows: Vec<String> = (0..30)
        .map(|i| {
            format!(
                r#"{{"seed": "seed-{i:02}", "name": "synthetic defect {i}", "defect_class": "synthetic class", "planted_files": ["src/synthetic.py"], "gates": {{"unit checks": "caught"}}}}"#
            )
        })
        .collect();
    format!(
        r#"{{"gates": ["unit checks"], "rows": [{}]}}"#,
        rows.join(", ")
    )
}

/// Assemble the pack standing above the floor and read it
/// back as a document.
fn pack_above_floor(dir: &Path) -> JsonValue {
    write(dir, "cl-pack.json", &cl_pack(1..=14));
    write(dir, "canary.json", &canary());
    let (code, err) = run(
        dir,
        &[
            "assemble",
            "--catchledger",
            "cl-pack.json",
            "--canaryfield",
            "canary.json",
            "--packs-dir",
            "packs",
        ],
    );
    assert_eq!(code, 0, "the assembly stands: {err}");
    let text =
        std::fs::read_to_string(dir.join("packs/001-unit-checks.json")).expect("the pack reads");
    parse(&text).expect("the pack parses")
}

/// A scratch standing with the pack, one ruling's record, and
/// a supplied body written into it, returning the paths the
/// door reads.
fn standing(
    tag: &str,
    ruling_word: &str,
    body_text: &str,
) -> (PathBuf, JsonValue, JsonValue, String) {
    let dir = scratch(tag);
    let pack = pack_above_floor(&dir);
    let (record, genuine_body) =
        generate_ruling(&pack, ruling_word, None, None).expect("the ruling generates");
    write(&dir, "pack.json", &render_json(&pack));
    write(&dir, "record.json", &render_json(&record));
    write(&dir, "body.md", body_text);
    (dir, pack, record, genuine_body)
}

fn run_door(dir: &Path, with_body: bool) -> (i32, String) {
    let mut args = vec![
        "validate-ruling",
        "--pack",
        "pack.json",
        "--ruling",
        "record.json",
    ];
    if with_body {
        args.push("--body");
        args.push("body.md");
    }
    run(dir, &args)
}

#[test]
fn test_a_generated_ruling_body_validates_beside_its_record() {
    let dir = scratch("library");
    let pack = pack_above_floor(&dir);
    let (record, body) = generate_ruling(&pack, "keep", None, None).expect("the ruling generates");
    assert!(
        validate_ruling_body(body.as_bytes(), &record, &pack).expect("the body validates"),
        "a body the generator wrote validates against its record and pack"
    );
    let (dir, _pack, _record, genuine) = standing("door", "keep", "");
    std::fs::write(dir.join("body.md"), &genuine).expect("the body stands");
    let (code, err) = run_door(&dir, true);
    assert_eq!(code, 0, "the door validates the pair: {err}");
}

#[test]
fn test_a_ruling_body_with_a_tampered_receipt_is_refused() {
    let (dir, _pack, _record, genuine) = standing("receipt", "keep", "");
    let tampered = genuine.replace("| Catches | 3 |", "| Catches | 30 |");
    assert_ne!(tampered, genuine, "the tamper lands");
    std::fs::write(dir.join("body.md"), &tampered).expect("the body stands");
    let (code, err) = run_door(&dir, true);
    assert_eq!(code, 1, "the door refuses at the standing exit");
    assert!(
        err.contains("the ruling body disagrees with the ruling record and its pack"),
        "the refusal carries the body words: {err}"
    );
}

#[test]
fn test_a_ruling_body_with_a_swapped_ruling_line_is_refused() {
    let (dir, _pack, _record, genuine) = standing("ruling-line", "keep", "");
    let tampered = genuine.replace("| Ruling | keep |", "| Ruling | kill |");
    assert_ne!(tampered, genuine, "the tamper lands");
    std::fs::write(dir.join("body.md"), &tampered).expect("the body stands");
    let (code, err) = run_door(&dir, true);
    assert_eq!(code, 1, "the door refuses at the standing exit");
    assert!(
        err.contains("the ruling body disagrees with the ruling record and its pack"),
        "the refusal carries the body words: {err}"
    );
}

#[test]
fn test_a_missing_ruling_body_is_refused_at_the_door() {
    let (dir, _pack, _record, _genuine) = standing("missing", "keep", "body");
    let (code, err) = run(
        &dir,
        &[
            "validate-ruling",
            "--pack",
            "pack.json",
            "--ruling",
            "record.json",
            "--body",
            "no-body.md",
        ],
    );
    assert_eq!(code, 1, "a missing body refuses at the standing exit");
    assert!(
        err.contains("the ruling body could not be read"),
        "the refusal names the missing body: {err}"
    );
}

#[test]
fn test_a_ruling_body_for_another_ruling_of_the_same_pack_is_refused() {
    let dir = scratch("other-ruling");
    let pack = pack_above_floor(&dir);
    let (record, _keep_body) =
        generate_ruling(&pack, "keep", None, None).expect("the keep ruling generates");
    let (_demote_record, demote_body) =
        generate_ruling(&pack, "demote", None, None).expect("the demote ruling generates");
    write(&dir, "pack.json", &render_json(&pack));
    write(&dir, "record.json", &render_json(&record));
    write(&dir, "body.md", &demote_body);
    let (code, err) = run_door(&dir, true);
    assert_eq!(code, 1, "the door refuses at the standing exit");
    assert!(
        err.contains("the ruling body disagrees with the ruling record and its pack"),
        "the body of another ruling of the same pack refuses: {err}"
    );
}

#[test]
fn test_a_ruling_body_missing_its_final_newline_is_refused() {
    let (dir, _pack, _record, genuine) = standing("shortened", "keep", "");
    assert!(genuine.ends_with('\n'), "the rendering ends in a newline");
    std::fs::write(dir.join("body.md"), &genuine[..genuine.len() - 1]).expect("the body stands");
    let (code, err) = run_door(&dir, true);
    assert_eq!(code, 1, "the door refuses at the standing exit");
    assert!(
        err.contains("the ruling body disagrees with the ruling record and its pack"),
        "one missing byte is a different document: {err}"
    );
}

#[test]
fn test_the_validate_ruling_door_without_a_body_validates_the_record_alone() {
    let (dir, _pack, _record, _genuine) = standing("record-alone", "keep", "not a body");
    let (code, err) = run_door(&dir, false);
    assert_eq!(
        code, 0,
        "the door without a body validates the record alone as it stands today: {err}"
    );
}

#[test]
fn test_a_tampered_record_is_refused_before_the_body_is_read() {
    let dir = scratch("record-first");
    let pack = pack_above_floor(&dir);
    let (record, body) = generate_ruling(&pack, "keep", None, None).expect("the ruling generates");
    let pairs: Vec<(String, JsonValue)> = record
        .as_object()
        .expect("the record stands as an object")
        .iter()
        .map(|(key, held)| {
            if key == "state_after_ruling" {
                (key.clone(), JsonValue::Text("advisory".to_string()))
            } else {
                (key.clone(), held.clone())
            }
        })
        .collect();
    write(&dir, "pack.json", &render_json(&pack));
    write(&dir, "record.json", &render_json(&JsonValue::Object(pairs)));
    write(&dir, "body.md", &body);
    let (code, err) = run_door(&dir, true);
    assert_eq!(code, 1, "the door refuses at the standing exit");
    assert!(
        err.contains("the ruling record disagrees with the pack it was ruled from"),
        "the record reading runs first and refuses in its own words: {err}"
    );
}
